        [1307176] = "Розміщує арканічне горно для рецептів, які його потребують, і надає всі переваги зачарованої лютні. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх зачарованої лютні, замінивши її. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307208] = "Застосування шокових заклять до невмерлих скорочує час відновлення «Удару бурі» на ${$s1/-1000}.1 с.",
        [1307223] = "Розміщує арканічний утилізатор, що дає змогу ефективніше розпорошувати предмети, і надає всі переваги зачарованої лютні. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх зачарованої лютні, замінивши її.\r\n Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307226] = "Розміщує залізну піч, потрібну для найскладніших кулінарних рецептів. Потребує кухонного вогнища поблизу. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307227] = "Будує звичайне багаття, що дає змогу готувати їжу та розмістити до $s1 додаткових табірних споруд. Гравці, які сидять або займаються ремеслом поблизу протягом $1229739d, отримують переваги інших табірних споруд.",
        [1307229] = "Встановлює табірний стілець, який дає вам та іншим гравцям, що сидять поблизу, $1229519s1% збільшення ймовірності критичного удару всіма закляттями й атаками; не поєднується з «Аурою совуха».\r\n\r\nПотребує багаття поблизу. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307230] = "Будує намет, який дає вам та іншим гравцям, що сидять поблизу, змогу збільшити запас відпочилого досвіду до $s2% рівня. Не діє, якщо запас відпочилого досвіду вже перевищує це значення.\r\n\r\nПотребує багаття поблизу. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307234] = "Викликає зачаровану лютню, яка дає вам та іншим гравцям, що сидять поблизу, $?$PL<10[28]?$PL<20[71]?$PL<30[114]?$PL<40[163]?$PL<50[211]?$PL<60[260][$1230653s1 ] збільшення броні$?$PL<10[]?$PL<30[ and ][, ]$?$PL>59[$1230653s2]?$PL>49[12]?$PL>39[9]?$PL>29[7]?$PL>19[4]?$PL>9[2][]$?$PL>9[ increase to all stats][]$?$PL>59[, and $1230653s3]?$PL>49[, and 16]?$PL>39[, and 12]?$PL>29[, and 6][]$?$PL>29[ increase to all resistances][], не поєднується зі «Знаком дикої природи».\r\n\r\nПотребує багаття поблизу. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307237] = "Будує експертне багаття, що дає змогу готувати їжу та розмістити до $s1 додаткових табірних споруд. Гравці, які сидять або займаються ремеслом поблизу протягом $1229739d, отримують переваги інших табірних споруд.",
        [1307239] = "Розгортає прапор, який дає вам та іншим членам Альянсу, що сидять поблизу, $?$PL<40[14]?$PL<50[19]?$PL<60[27][$1229718s1] додаткового духу; не поєднується з «Божественним духом».\r\n\r\nПотребує багаття поблизу. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307240] = "Розгортає прапор, який дає вам та іншим членам Орди, що сидять поблизу, $?$PL<40[14]?$PL<50[19]?$PL<60[27][$1229718s1] додаткового духу; не поєднується з «Божественним духом».\r\n\r\nПотребує багаття поблизу. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307242] = "Розміщує ферментатор, який дає змогу створювати певні реагенти, і надає всі переваги криниці мани. Потребує багаття поблизу. Можна розмістити поверх криниці мани, замінивши її. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307243] = "Розміщує польовий довідник, який гравці можуть прочитати, щоб отримати «Вистежування звірів», і надає всі переваги табірного стільця. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх табірного стільця, замінивши його.\r\n Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307244] = "Розпаковує аптечку першої допомоги, яка дає вам та іншим гравцям, що сидять поблизу, $?$PL<12[3]?$PL<24[8]?$PL<36[21]?$PL<48[34]?$PL<60[45][$1230124s1] додаткової витривалості; не поєднується зі «Словом сили: Стійкість».\r\n\r\nПотребує багаття поблизу. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307245] = "Розміщує невеликий акваріум, який дає вам та іншим гравцям, що сидять поблизу, $1230098s1% збільшення характеристик; не поєднується з «Благословенням королів».\r\n\r\nПотребує багаття поблизу. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307246] = "Розміщує рибальську хатину, що дає змогу ловити рідкісну рибу протягом $1280342d, надає принади до навички рибальства та всі переваги акваріума. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх акваріума, замінивши його.\r\n Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307247] = "Розміщує рибальську стійку, що дає змогу ловити незвичайну рибу протягом $1280341d, надає принади до навички рибальства та всі переваги акваріума. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх акваріума, замінивши його. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307248] = "Розміщує теплицю, у якій із посадженого насіння з часом виростають трави, і надає всі переваги пахощової свічки. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх пахощової свічки, замінивши її.\r\n Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307251] = "Запалює пахощову свічку, яка дає вам та іншим гравцям, що сидять поблизу, $?$PL<14[2]?$PL<28[6]?$PL<42[12]?$PL<56[18][$1229513s1] додаткового інтелекту; не поєднується з «Арканічним інтелектом».\r\n\r\nПотребує багаття поблизу. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307252] = "Будує багаття підмайстра, що дає змогу готувати їжу та розмістити до $s1 додаткових табірних споруд. Гравці, які сидять або займаються ремеслом поблизу протягом $1229739d, отримують переваги інших табірних споруд.",
        [1307254] = "Встановлює магнітний камінь, який дає вам та іншим гравцям, що сидять поблизу, $?$PL<12[12]?$PL<22[20]?$PL<32[32]?$PL<42[49]?$PL<52[67][$1230164s1] додаткової сили атаки ближнього бою; не поєднується з «Благословенням могутності».\r\n\r\nПотребує багаття поблизу. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307255] = "Розміщує ткацький верстат для рецептів, які його потребують, і надає всі переваги прапора фракції. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх прапора фракції, замінивши його. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307257] = "Викладає «Бенкет Пиріжка» з їжею, що підвищує витривалість. Потребує кухонного вогнища поблизу. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307259] = "Будує криницю мани, яка дає вам та іншим гравцям, що сидять поблизу, відновлення $?$PL<24[10]?$PL<34[15]?$PL<44[20]?$PL<54[24][$1230587s1] мани кожні 5 с; не поєднується з «Благословенням мудрості».\n\nПотребує багаття поблизу. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307261] = "Розміщує майстерне горно для рецептів, які його потребують, і надає всі переваги точильного круга. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх точильного круга, замінивши його. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307264] = "Розміщує розплавлену ливарню для рецептів, які її потребують, і надає всі переваги магнітного каменя. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх магнітного каменя, замінивши його. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307265] = "Розміщує лабораторію чумного лікаря з цілющими зіллями й припарками та надає всі переваги аптечки першої допомоги. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх аптечки першої допомоги, замінивши її. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307266] = "Викликає робота-реагентника, у якого ви та інші гравці поблизу можете купувати реагенти. Потребує багаття поблизу. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307288] = "Завдає цілі $s1 шкоди від тіні та висмоктує $s3 мани. Завдає невмерлим у $s2 рази \r\nбільше шкоди.",
        [1307315] = "Шкідливе закляття з певною ймовірністю завдає цілі $1307288s1 шкоди від тіні та висмоктує $1307288s3 мани. Завдає невмерлим у $1307288s2 рази більше шкоди.\r\n",
        [1307334] = "Збільшує зцілення заклять і ефектів на величину до $s1, а їхню шкоду — на величину до $s2 у примарних місцевостях.",
        [1307385] = "Викликає ремонтного робота, у якого ви та інші гравці поблизу можете купувати реагенти й ремонтувати спорядження. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх робота-реагентника, замінивши його. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307386] = "Розміщує сад каміння, де з часом з’являється звичайна гірнича жила, і надає всі переваги магнітного каменя. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх магнітного каменя, замінивши його. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307387] = "Розміщує гібридизатор насіння, що дає змогу розмножувати насіння або поєднувати його у рідкісніші сорти, і надає всі переваги пахощової свічки. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх пахощової свічки, замінивши її.\r\n Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307391] = "Розміщує швейну машину для рецептів, які її потребують, і надає всі переваги табірного намету. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх табірного намету, замінивши його. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307392] = "Будує точильний круг, який дає вам та іншим гравцям, що сидять поблизу, $?$PL<24[6]?$PL<38[11]?$PL<52[20][$1230172s1] додаткової сили; не поєднується з «Тотемом сили землі».\r\n\r\nПотребує багаття поблизу. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307393] = "Розміщує прядку, що дає змогу створювати певні реагенти, і надає всі переваги прапора фракції. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх прапора фракції, замінивши його. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307395] = "Розміщує козли для дублення, що дають змогу створювати певні реагенти, і надає всі переваги табірного намету. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх табірного намету, замінивши його. Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307396] = "Розміщує дослідження токсинів із цілющими зіллями та протиотрутою й надає всі переваги аптечки першої допомоги. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх аптечки першої допомоги, замінивши її.\r\n Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307397] = "Розміщує верстак мисливця з 1 пасткою та надає всі переваги табірного стільця. Потребує багаття поблизу. \r\n\r\nМожна розмістити поверх табірного стільця, замінивши його.\r\n\r\n Усі табірні споруди мають спільний час відновлення $1308027d.",
        [1307400] = "Критичні удари «Гніву» подовжують тривалість вашого «Рою комах» на цілі на ${$s1/1000} с. Проти звірів тривалість додатково збільшується на ${$s2/1000} с.",
