        [1319259] = "Завдає ворогу $s1 шкоди й збільшує отриману ним шкоду від святості на $s2 за кожен «Удар хрестоносця». Може накладатися до 2 разів. Триває $d.",
        [1319260] = "Збільшує швидкість на $s1% усім союзникам у межах $r м.",
        [1319289] = "Перевтілюється в одну з кількох могутніх форм, посилюючи бойові можливості.\r\n\r\n$?pc164317[$@spellicon9634 Образ лютого ведмедя\r\nПеретворює на лютого ведмедя, збільшуючи силу атак ближнього бою на $9635s4, внесок броні від предметів на $9635s1% і здоров’я на $9635s3. Також захищає заклинача від ефектів Перетворення та дає змогу використовувати різні ведмежі здібності.\r\n\r\nЗміна форми звільняє заклинача від Перетворення та ефектів, що обмежують рух.][$@spellicon5487 Образ ведмедя\r\nПеретворює на ведмедя, збільшуючи силу атак ближнього бою на $1178s4, внесок броні від предметів на $1178s1% і здоров’я на $1178s2. Також захищає заклинача від ефектів Перетворення та дає змогу використовувати різні ведмежі здібності.\r\n\r\nЗміна форми звільняє заклинача від Перетворення та ефектів, що обмежують рух.]\r\n\r\n$?pc117122[$@spellicon768 Образ кота\r\nПеретворює на котячу форму, збільшуючи силу атаки ближнього бою на $3025s1 плюс спритність.  Також захищає заклинача від ефектів Перетворення та дозволяє використовувати різні котячі здібності.\r\n\r\nПеретворення звільняє заклинача від Перетворення та ефектів, що обмежують рух.][]\r\n\r\n$?pc117124[$@spellicon783 Похідний образ\r\nПеретворює друїда на похідну форму, збільшуючи швидкість руху на $5419s1%.  Також захищає заклинача від ефектів Перетворення.  Можна використовувати лише просто неба.\r\n\r\nПеретворення звільняє заклинача від Перетворення та ефектів, що обмежують рух.][]\r\n\r\n$?pc117126[$@spellicon1066 Водний образ\r\nПеретворює на водну форму, збільшуючи швидкість плавання на $5421s1% і дозволяючи друїду дихати під водою.  Також захищає заклинача від ефектів Перетворення.\r\n\r\nПеретворення звільняє заклинача від Перетворення та ефектів, що обмежують рух.][]\r\n\r\n$?pc164521[$@spellicon24858 Moonkin Form\r\nПеретворює друїда на місячного совуха. У цій формі внесок броні від предметів збільшується на $24905s1%, «Знамення ясності» має на $s5% вищий шанс спрацювання, а ймовірність критичного удару всіх членів групи в межах $24907a1 м збільшується на $24907s1%; не сумісне з «Ватажком зграї». У формі совуха не можна застосовувати закляття зцілення.\r\n\r\nЗміна форми звільняє заклинача від поліморфії та ефектів, що обмежують рух.][]",
        [1319309] = "$@spellicon24907 Аура совуха\r\nЗбільшує імовірність критичного удару на $s1%.\r\n\r\n$@spellicon24932 Ватажок зграї\r\nЗбільшує імовірність критичного удару на $s1%.",
        [1319310] = "Поживна їжа надала вам ефект ситості, збільшуючи броню..",
        [1319311] = "Відновлює $o1 здоров’я протягом $d.  Під час їжі потрібно залишатися сидячи. Якщо їсти щонайменше 10 секунд, ви отримаєте ситість і $s2 броні на $1319310d. $?pc142418[Additionally, experience gained from kills is increased by $s1%.][]",
        [1319378] = "Завдає $s1 шкоди від аркани.",
        [1319421] = "Мотивує бійця Варти Смерті.",
        [1319423] = "Швидкість руху збільшено на $s1% у Тернистій долині та Річкових галявинах.",
        [1319426] = "Швидкість руху збільшено на $s1% у Тернистій долині та Річкових галявинах.",
        [1319427] = "Швидкість руху збільшено на $s1% у Тернистій долині та Річкових галявинах.",
        [1319446] = "Збільшує швидкість цільової істоти на 1%. Накопичується!",
        [1319453] = "Кладе святковий подарунок, який хтось може розгорнути.",
        [1319507] = "Приймає бойову стійку, змінюючи доступні здібності й бойові бонуси.\r\n\r\n$@spellicon2457 Бойова стійка\r\nЗбалансована бойова стійка.\r\n\r\n$?pc164518[$@spellicon71 Захисна стійка\r\nЗахисна бойова стійка.  Зменшує отриману шкоду на $7376s1%, а завдану шкоду — на $7376s2%.  Збільшує всю створювану загрозу на $?a12792[${($7376s3+100)*($12792s1/100+1)-100)}.1%][$7376s3%].][]\r\n\r\n$?pc164519[$@spellicon2458 Стійка берсерка\r\nАгресивна стійка. Шанс критичного удару збільшено на $7381s1%, а всю отриману шкоду — на $7381s2%.][]",
        [1319611] = "Спілкується зі Смарагдовим Сном, щоб підкорити Нітуса.",
        [1319652] = "Накладає на ціль могутнє прокляття.\r\n\r\n$?pc164709[$@spellicon440892 Прокляття стихій \r\nCurses the target for $d, reducing Magic resistances by $s1 and increases Magic damage taken by $s2%. Only one Curse per Warlock can be active on any one target. ][]$?pc164710[$@spellicon1311676 Прокляття стихій \r\nCurses the target for $d, reducing Magic resistances by $s1 and increases Magic damage taken by $s2%. Only one Curse per Warlock can be active on any one target.\r\n ][]$?pc164712[$@spellicon1311677 Прокляття стихій\r\nCurses the target for $d, reducing Magic resistances by $s1 and increases Magic damage taken by $s2%. Only one Curse per Warlock can be active on any one target.\r\n][]$?pc164714[$@spellicon1311680 Прокляття стихій\r\nCurses the target for $d, reducing Magic resistances by $s1 and increases Magic damage taken by $s2%. Only one Curse per Warlock can be active on any one target.][]\r\n\r\n$?pc164596[$@spellicon702 Прокляття слабкості\r\nЗменшує фізичну шкоду, яку завдає ціль, на $s1 протягом $d. На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника.][]$?pc164597[$@spellicon1108 Прокляття слабкості\r\nЗменшує фізичну шкоду, яку завдає ціль, на $s1 протягом $d. На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника.][]$?pc164598[$@spellicon6205 Прокляття слабкості\r\nЗменшує фізичну шкоду, яку завдає ціль, на $s1 протягом $d. На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника.][]$?pc164599[$@spellicon7646 Прокляття слабкості\r\nЗменшує фізичну шкоду, яку завдає ціль, на $s1 протягом $d. На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника.][]$?pc164600[$@spellicon11707 Прокляття слабкості\r\nЗменшує фізичну шкоду, яку завдає ціль, на $s1 протягом $d. На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника.][]$?pc164601[$@spellicon11708 Прокляття слабкості\r\nЗменшує фізичну шкоду, яку завдає ціль, на $s1 протягом $d. На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника.][]\r\n\r\n$?pc164594[$@spellicon1714 Прокляття мов\r\nЗмушує ціль говорити демонічною мовою, збільшуючи час застосування всіх заклинань на $s1%. На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника. Триває $d.][]$?pc164595[$@spellicon11719 Прокляття мов\r\nЗмушує ціль говорити демонічною мовою, збільшуючи час застосування всіх заклинань на $s1%. На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника. Триває $d.][]\r\n\r\n$?pc164590[$@spellicon704 Прокляття безрозсудності\r\nПроклинає ціль безрозсудністю, зменшуючи її броню на $s2 протягом $d. Прокляті вороги не тікатимуть і ігноруватимуть ефекти Страху та Жаху. На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника.][]$?pc164591[$@spellicon7658 Прокляття безрозсудності\r\nПроклинає ціль безрозсудністю, зменшуючи її броню на $s2 протягом $d. Прокляті вороги не тікатимуть і ігноруватимуть ефекти Страху та Жаху. На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника.][]$?pc164592[$@spellicon7659 Прокляття безрозсудності\r\nПроклинає ціль безрозсудністю, зменшуючи її броню на $s2 протягом $d. Прокляті вороги не тікатимуть і ігноруватимуть ефекти Страху та Жаху. На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника.][]$?pc164593[$@spellicon11717 Прокляття безрозсудності\r\nПроклинає ціль безрозсудністю, зменшуючи її броню на $s2 протягом $d. Прокляті вороги не тікатимуть і ігноруватимуть ефекти Страху та Жаху. На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника.][]\r\n\r\n$?pc164724[$@spellicon18223 Curse of Exhaustion\r\nЗменшує швидкість руху цілі на $s1% протягом $d.  На одній цілі одночасно може діяти лише одне Прокляття від одного чорнокнижника.][]",
        [1319669] = "$?pc164709[$@spellicon440892 Прокляття стихій \r\nCurses the target for $d, reducing Magic resistances by $s1 and increases Magic damage taken by $s2%. Only one Curse per Warlock can be active on any one target. ][]$?pc164710[$@spellicon1311676 Прокляття стихій \r\nCurses the target for $d, reducing Magic resistances by $s1 and increases Magic damage taken by $s2%. Only one Curse per Warlock can be active on any one target.\r\n ][]$?pc164712[$@spellicon1311677 Прокляття стихій\r\nCurses the target for $d, reducing Magic resistances by $s1 and increases Magic damage taken by $s2%. Only one Curse per Warlock can be active on any one target.\r\n][]$?pc164714[$@spellicon1311680 Прокляття стихій\r\nCurses the target for $d, reducing Magic resistances by $s1 and increases Magic damage taken by $s2%. Only one Curse per Warlock can be active on any one target.][]\r\n\r\n$?pc164596[$@spellicon702 Прокляття слабкості\r\nЗменшує фізичну шкоду, яку завдає ціль, на $s1 протягом $d. На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника.][]$?pc164597[$@spellicon1108 Прокляття слабкості\r\nЗменшує фізичну шкоду, яку завдає ціль, на $s1 протягом $d. На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника.][]$?pc164598[$@spellicon6205 Прокляття слабкості\r\nЗменшує фізичну шкоду, яку завдає ціль, на $s1 протягом $d. На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника.][]$?pc164599[$@spellicon7646 Прокляття слабкості\r\nЗменшує фізичну шкоду, яку завдає ціль, на $s1 протягом $d. На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника.][]$?pc164600[$@spellicon11707 Прокляття слабкості\r\nЗменшує фізичну шкоду, яку завдає ціль, на $s1 протягом $d. На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника.][]$?pc164601[$@spellicon11708 Прокляття слабкості\r\nЗменшує фізичну шкоду, яку завдає ціль, на $s1 протягом $d. На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника.][]\r\n\r\n$?pc164594[$@spellicon1714 Прокляття мов\r\nЗмушує ціль говорити демонічною мовою, збільшуючи час застосування всіх заклинань на $s1%. На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника. Триває $d.][]$?pc164595[$@spellicon11719 Прокляття мов\r\nЗмушує ціль говорити демонічною мовою, збільшуючи час застосування всіх заклинань на $s1%. На одній цілі одночасно може діяти лише одне прокляття від одного чорнокнижника. Триває $d.][]",
        [1319759] = "Накладає на ціль могутню згубу.\r\n\r\n$?pc164577[$@spellicon980 Прокляття агонії\r\nУражає ціль агонією, завдаючи $o1 шкоди від тіні протягом $d. Спочатку шкода завдається повільно, але посилюється з наближенням Кари до завершення. На одній цілі одночасно може діяти лише одна кара від одного чорнокнижника.][]$?pc164578[$@spellicon1014 Прокляття агонії\r\nУражає ціль агонією, завдаючи $o1 шкоди від тіні протягом $d. Спочатку шкода завдається повільно, але посилюється з наближенням Кари до завершення. На одній цілі одночасно може діяти лише одна кара від одного чорнокнижника.][]$?pc164579[$@spellicon6217 Прокляття агонії\r\nУражає ціль агонією, завдаючи $o1 шкоди від тіні протягом $d. Спочатку шкода завдається повільно, але посилюється з наближенням Кари до завершення. На одній цілі одночасно може діяти лише одна кара від одного чорнокнижника.][]$?pc164580[$@spellicon11711 Прокляття агонії\r\nУражає ціль агонією, завдаючи $o1 шкоди від тіні протягом $d. Спочатку шкода завдається повільно, але посилюється з наближенням Кари до завершення. На одній цілі одночасно може діяти лише одна кара від одного чорнокнижника.][]$?pc164581[$@spellicon11712 Прокляття агонії\r\nУражає ціль агонією, завдаючи $o1 шкоди від тіні протягом $d. Спочатку шкода завдається повільно, але посилюється з наближенням Кари до завершення. На одній цілі одночасно може діяти лише одна кара від одного чорнокнижника.][]$?pc164582[$@spellicon11713 Прокляття агонії\r\nУражає ціль агонією, завдаючи $o1 шкоди від тіні протягом $d. Спочатку шкода завдається повільно, але посилюється з наближенням Кари до завершення. На одній цілі одночасно може діяти лише одна кара від одного чорнокнижника.][]\r\n\r\n$?pc164747[$@spellicon603 Прокляття приреченості\r\nНакликає на ціль неминучу загибель, завдаючи $s1 шкоди від тіні через $d.  Якщо ціль загине від цієї шкоди, є шанс викликати Вартового Скверни.  Не можна застосовувати до гравців. На одній цілі одночасно може діяти лише одна кара від одного чорнокнижника.\r\n][]\r\n$?pc164748[$@spellicon1225228 Bane of Havoc\r\nAfflicts the target for $d, causing $s1% of all damage done by the Warlock to other targets to also be dealt to the cursed target. Bane of Havoc is limited to 1 target, and only one Bane per Warlock can be active on any one target.][]",
